"""Read ids.txt and print the next order id."""

import sys

CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    """Convert a non-negative integer to base-36."""
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(CHARS[n % 36])
        n //= 36
    return "".join(reversed(digits))


def next_id(current: str) -> str:
    """Given an ORD-XXXX id, return the next sequential id."""
    suffix = current[4:]  # strip "ORD-"
    val = int(suffix, 36)
    val += 1
    next_suffix = to_base36(val).upper().zfill(4)
    return f"ORD-{next_suffix}"


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    current = lines[-1]  # most recent id (last line)
    print(next_id(current))


if __name__ == "__main__":
    main()

